fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
%fit_data_file = 'FitEn_cut800br200_2D_fit_bgSer.mat';%Externaly 2-exponent fit fixed bg at high momentum.
%fit_data_file = 'FitEn_cut800br100_2D_dirGH_dE20_fix_bg_slope.mat'
fit_data_file =  'FitEn_cut800ref110_2D_dirGH_dE20_fix_bg_slope.mat' %[output:6e68183d]
if ~exist('fit_resEi800','var')
    ld = load(fullfile(fit_data_path,fit_data_file));
    if isfield(ld,'fit_resEi800')
        fit_resEi800 = ld.fit_resEi800;
    else
        fit_resEi800 = ld.fit_res;
    end
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_cut_data_file = 'multicuts_fit_dataGH_ei800meV.mat';
if ~exist('cuts2fit800','var')
    ld = load(fullfile(data_path,fit_cut_data_file));
    cuts2fit800 = ld.cuts2fit800;
end
cuts2fit = cuts2fit800;
%fit_res = fit_resEi800;
fit_res  = ld.fit_res;
mi = maps_instrument(787,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = {cuts2fit800.cut2fit010_dir100} %[output:15e6db94]
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end
cuts2fit800.cut2fit010_dir100 = cl{1};
the2Dcuts =cl;
%%
[Sgnl,J0,G] = plot_SJG_results(fit_res,'b',{'S','J0','gamma'},{[0.5,2],[20,60],[0,200]});
%[output:5b5d0ff1] %[output:0cc9d144] %[output:25e0da0a]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1));
e_min = Sgnl.x(1);

%%
En = 160 %[output:9131836c]
dE_step = 4; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
%the2Dcuts = cuts2fit.cutsS_list;%(1:2);
the2Dcuts =cl;

%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
%the2Dcuts{3} = cut(the2Dcuts{3},[-1,0.02,1],[]);
lfit_par = fit_res.all_fit_par(en_idx);
en_range = lfit_par.en_range;
[fit_obj,fit_par,figa,figb]=refit_singleset_peaks(the2Dcuts,en_range,lfit_par,0.2,true,false); %[output:294adba0] %[output:4646c328] %[output:25306da4] %[output:5306f648] %[output:26ac43a6] %[output:4c8a4983] %[output:0487c2c2]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
%fit_res.all_fit_par(en_idx).p = fit_par.p;
acolor r
plot(fit_res.S);ly 0 1.5;liny; %[output:5b86da15]
acolor b
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 1.5;liny;keep_figure %[output:5b86da15]

acolor r
plot(fit_res.J0);ly 10 50;liny; %[output:29084818]
acolor b
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 10 50;keep_figure %[output:29084818]

acolor r
plot(fit_res.gamma);ly 0 200;liny; %[output:2ac50e5b]
acolor b
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 200;keep_figure %[output:2ac50e5b]
%%
[fit_res,Sg,J0,G] = refit_data_around_peaks(the2Dcuts,fit_res,0.2,true); %[output:6f4d6ade] %[output:3ffcebf0] %[output:56773c4d] %[output:048a9ed0] %[output:72fc3513] %[output:0fd40c8e] %[output:64c60e5a] %[output:63fd59dd] %[output:89319643] %[output:1e6c687c] %[output:073fc81e] %[output:69a498e8] %[output:404816b4] %[output:5b841b24] %[output:3b91c9d4] %[output:9432d60f] %[output:03f8843a] %[output:4e330730] %[output:069e262a] %[output:240dfbd7] %[output:210907ea] %[output:886d09f4] %[output:286b8ba2] %[output:166715c7] %[output:59417693] %[output:109c7f8f] %[output:3a08a6e2] %[output:89ae6778] %[output:9c1ffd59] %[output:51756e05] %[output:4dee249e] %[output:7a6ff2c5] %[output:5d38eec7] %[output:363b5356] %[output:433b19fc] %[output:4451779c] %[output:6ec1ceb9] %[output:00f8491b] %[output:8cea95ec] %[output:4c6f9afe] %[output:09e2f572] %[output:48fe2c47] %[output:9129a99f] %[output:0b941617] %[output:743bd2bf] %[output:275bc1fb] %[output:7438701f] %[output:745954e5] %[output:9e3c7b28] %[output:3e6a3add] %[output:342a9d2d] %[output:46ca591c] %[output:710e4483] %[output:0046c061] %[output:2640d936] %[output:2d97c3ba] %[output:8b1aebee] %[output:0e4460d4] %[output:3102524b] %[output:6a2dbf10] %[output:32e6cfb6] %[output:582033a7] %[output:89af33a1] %[output:4da294b0] %[output:116f0a22] %[output:49e3d8bf] %[output:468478e7] %[output:1e97b8cd] %[output:125267ca] %[output:4dcbae2b] %[output:17633366] %[output:9d8f6c46] %[output:97f9c4c1] %[output:8d9319a8] %[output:6f7c016d] %[output:773b2666] %[output:59e1e81e] %[output:633cb3d6] %[output:07fcebfd] %[output:3b65f978] %[output:53f3263a] %[output:36553e32] %[output:1ac20984] %[output:1d355953] %[output:8392a8a1] %[output:1254e2bc] %[output:055f0f61] %[output:2dcb2928] %[output:2f886317] %[output:338b8a53] %[output:90c71ac6] %[output:5afb41fc] %[output:86f1f0e5]
%%

num_bp = cellfun(@(x)(numel(x.bp)),peak_fit_par);
mbp = max(num_bp);
bp_plot = nan(mbp,numel(num_bp));
bp_sig  = nan(mbp,numel(num_bp));
en_axis = Sg.x;
for i=1:numel(peak_fit_par)
    bpl = peak_fit_par{i}.bp;
    bgs = peak_fit_par{i}.bsig;
    for j=1:numel(bpl)
        if iscell(bpl)
            bp_plot(j,i)= bpl{j}(1);
            bp_sig(j,i) = bgs{j}(1);
        else
            bp_plot(j,i) = bpl(1);
            bp_sig(j,i) = bgs(1);
        end
    end
end
bg_data = repmat(IX_dataset_1d(),1,4);
for j=1:4
    bg_data(j) = IX_dataset_1d(en_axis,bp_plot(j,:),bp_sig(j,:));
end
pd(bg_data); ly -10 10; keep_figure;
%%
acolor r
plot(fit_res.S);ly 0 1.5;liny; %[output:978bf4d8]
acolor b
pd(Sg);ly 0 1.5;liny;keep_figure %[output:978bf4d8]

acolor r
plot(fit_res.J0);ly 10 50;liny; %[output:9911232f]
acolor b
pd(J0);ly 10 50;keep_figure %[output:9911232f]

acolor r
plot(fit_res.gamma);liny; %[output:1a67c8fe]
acolor b
pd(G);ly 0 250;keep_figure %[output:1a67c8fe]
%%

%%
% fit_res.Speak_varsl = Sg;
% fit_res.J0peak_varsl = J0;
% fit_res.gamma_peak_varsl = G;
fit_res.Speak = Sg;
fit_res.J0peak = J0;
fit_res.gamma_peak = G;
    
fit_res.peak_fit_par = [peak_fit_par{:}];
fit_res.peak_fit_FixSlope_par = fit_res.peak_fit_par;
fit_resEi800 = fit_res;
save(fullfile(fit_data_path,fit_data_file),"fit_resEi800");

